import limited_client as robot, numpy as np
r=robot.observe(camera=2)['robot']; q=np.array(r['joint_positions'],float)
a=np.r_[q.copy(),0.001,0.002]; a[1]-=0.025
print('before',r); print('lift target',a.tolist())
try: print('lift',robot.step(a.tolist()))
except Exception as e: print('ERROR',repr(e))
for c in (2,0):
 o=robot.observe(camera=c); print('camera',c,'robot',o['robot']); print('status',robot.status())
