import limited_client as robot, numpy as np
for c in (0,1,2):
 o=robot.observe(camera=c)
 print('camera',c,'state',o['robot'],'status',robot.status())
 if c==2:
  for u,v in [(280,300),(318,300),(350,300),(280,320),(318,320),(350,320),(260,350)]:
   z=float(np.median(o['depth_m'][v-2:v+3,u-2:u+3])); pc=np.linalg.inv(o['intrinsic'])@np.array([u,v,1.])*z
   print('pixel',u,v,'z',z,'world',(o['camera_to_world']@np.r_[pc,1])[:3])
